export const BODY: string = "\n<p>تصویر پر متن اس وقت کام کرتا ہے جب وہ پڑھا جا سکے۔ خوبصورت متن جو پڑھا نہ جا سکے، وہ ناکام ہے۔ پڑھنے کی اہلیت سب سے پہلے آتی ہے۔</p>\n<p>متن کی پڑھنے کی اہلیت کنٹراسٹ، فونٹ، سائز اور جگہ پر منحصر ہے۔ ان چاروں کو درست کریں تو متن ہر جگہ پڑھا جاتا ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ کنٹراسٹ کیسے ناپیں، رنگ کیسے چنیں، اور مصروف تصویر پر متن کیسے رکھیں۔ متن شامل کرنے کے لیے <a href=\"/ur/tasveer-par-text-likhein/\">تصویر پر متن شامل کریں</a> استعمال کریں۔</p>\n<h2 id=\"why-readability-matters\">پڑھنے کی اہلیت کیوں اہم ہے</h2>\n<p>پڑھنے کی اہلیت اس لیے اہم ہے کہ لوگ تصویر کو سیکنڈوں میں دیکھتے ہیں۔ اگر متن پڑھا نہ جا سکے تو پیغام ضائع ہو جاتا ہے۔</p>\n<p>سوشل میڈیا پر لوگ تیزی سے سکرول کرتے ہیں۔ متن جو پہلی نظر میں پڑھا جا سکے، وہی رک کر پڑھا جاتا ہے۔</p>\n<p>پڑھنے کی اہلیت رسائی کے لیے بھی اہم ہے۔ کمزور نظر والے لوگوں کو متن پڑھنے میں مشکل ہوتی ہے، اگر کنٹراسٹ کم ہو۔</p>\n<h2 id=\"contrast-ratio-basics\">کنٹراسٹ ریشو کی بنیاد</h2>\n<p>کنٹراسٹ ریشو متن اور پس منظر کے رنگوں کے فرق کو ناپتا ہے۔ 4.5:1 کا ریشو عام متن کے لیے کم سے کم ہے۔</p>\n<p>کنٹراسٹ جتنا زیادہ ہو، متن اتنا ہی آسان پڑھا جاتا ہے۔ سفید پس منظر پر کالا متن سب سے زیادہ کنٹراسٹ دیتا ہے۔</p>\n<p>کنٹراسٹ ناپنے کے لیے آن لائن ٹول استعمال کریں۔ اندازہ نہ لگائیں، ناپ کر دیکھیں۔</p>\n<h2 id=\"choosing-text-colour\">متن کا رنگ کیسے چنیں</h2>\n<p>متن کا رنگ پس منظر کے برعکس چنیں۔ ہلکے پس منظر پر گہرا متن، گہرے پس منظر پر ہلکا متن۔</p>\n<p>رنگ چننے میں تصویر کا رنگ بھی دیکھیں۔ اگر تصویر میں کئی رنگ ہوں تو سفید یا کالا متن محفوظ ہے۔</p>\n<p>رنگین متن خوبصورت لگتا ہے، مگر پڑھنے میں مشکل ہو سکتا ہے۔ رنگ صرف اس وقت استعمال کریں جب کنٹراسٹ کافی ہو۔</p>\n<h2 id=\"choosing-background-areas\">متن کے لیے پس منظر کی جگہ</h2>\n<p>متن کے لیے تصویر کا سادہ حصہ چنیں، جہاں رنگ ایک جیسا ہو۔ مصروف حصے پر متن پڑھا نہیں جاتا۔</p>\n<p>اگر تصویر میں سادہ جگہ نہ ہو تو متن کے پیچھے ہلکا پینل لگائیں۔ پینل متن کو الگ کرتا ہے۔</p>\n<p>متن کو تصویر کے کنارے پر رکھیں، جہاں اکثر سادہ جگہ ہوتی ہے۔ درمیان میں متن تصویر کو ڈھانپ دیتا ہے۔</p>\n<h2 id=\"font-choice\">فونٹ کا انتخاب</h2>\n<p>فونٹ سادہ اور صاف ہونا چاہیے۔ سجاوٹی فونٹ خوبصورت لگتا ہے، مگر پڑھنے میں مشکل ہوتا ہے۔</p>\n<p>ایک تصویر پر ایک یا دو فونٹ استعمال کریں۔ زیادہ فونٹ تصویر کو بے ترتیب بنا دیتے ہیں۔</p>\n<p>فونٹ کا وزن بھی اہم ہے: بولڈ متن چھوٹے سائز میں بھی پڑھا جاتا ہے، ہلکا متن نہیں۔</p>\n<h2 id=\"font-size-rules\">فونٹ سائز کے اصول</h2>\n<p>فونٹ سائز اتنا بڑا رکھیں کہ فون پر بھی پڑھا جا سکے۔ فون پر تصویر چھوٹی دکھائی دیتی ہے، اس لیے متن بڑا ہونا چاہیے۔</p>\n<p>اہم متن سب سے بڑا رکھیں، تفصیل چھوٹی۔ سائز کا فرق درجہ بندی بناتا ہے۔</p>\n<p>فونٹ سائز آزمانے کے لیے تصویر کو فون پر دیکھیں۔ اگر متن پڑھا جا سکے تو سائز درست ہے۔</p>\n<h2 id=\"line-length-and-spacing\">لائن کی لمبائی اور فاصلہ</h2>\n<p>لائن زیادہ لمبی نہ رکھیں۔ لمبی لائن پڑھنے میں مشکل ہوتی ہے، خاص طور پر فون پر۔</p>\n<p>لائنوں کے درمیان فاصلہ رکھیں، تاکہ متن سانس لے سکے۔ گھنا متن پڑھا نہیں جاتا۔</p>\n<p>متن کو چھوٹے حصوں میں توڑیں۔ ایک بڑا پیراگراف تصویر پر نہیں چلتا، چھوٹے حصے چلتے ہیں۔</p>\n<h2 id=\"outlines-and-shadows\">آؤٹ لائن اور سایہ</h2>\n<p>آؤٹ لائن متن کے گرد ایک لکیر ہے، جو اسے پس منظر سے الگ کرتی ہے۔ آؤٹ لائن مصروف تصویر پر بہت کام آتی ہے۔</p>\n<p>سایہ بھی متن کو الگ کرتا ہے، مگر ہلکا سایہ استعمال کریں۔ گہرا سایہ متن کو گندا بنا دیتا ہے۔</p>\n<p>آؤٹ لائن یا سایہ، دونوں میں سے ایک چنیں۔ دونوں ایک ساتھ متن کو بھاری بنا دیتے ہیں۔</p>\n<h2 id=\"background-panels\">پس منظر کے پینل</h2>\n<p>پینل متن کے پیچھے ایک رنگین ڈبہ ہے، جو متن کو پڑھنے کے قابل بناتا ہے۔ پینل مصروف تصویر پر سب سے اچھا حل ہے۔</p>\n<p>پینل کا رنگ ہلکا شفاف رکھیں، تاکہ تصویر بھی نظر آئے اور متن بھی پڑھا جا سکے۔ مکمل ٹھوس پینل تصویر کو ڈھانپ دیتا ہے۔</p>\n<p>پینل کا سائز متن سے تھوڑا بڑا رکھیں، تاکہ متن سانس لے سکے۔</p>\n<h2 id=\"text-over-busy-photos\">مصروف تصویر پر متن</h2>\n<p>مصروف تصویر پر متن رکھنا سب سے مشکل کام ہے۔ پہلا حل یہ ہے کہ تصویر کو دھندلا کریں، تاکہ متن الگ نظر آئے۔</p>\n<p>دوسرا حل یہ ہے کہ تصویر کے اوپر گہرا رنگ لگائیں اور اس پر سفید متن لکھیں۔ یہ طریقہ ہر تصویر پر کام کرتا ہے۔</p>\n<p>تیسرا حل یہ ہے کہ متن کو تصویر کے سادہ حصے میں رکھیں۔ تینوں میں سے جو بہتر لگے، وہ چنیں۔</p>\n<h2 id=\"text-over-faces\">چہروں پر متن</h2>\n<p>چہرے پر متن نہ رکھیں۔ چہرہ تصویر کا سب سے اہم حصہ ہے، اور متن اسے ڈھانپ دیتا ہے۔</p>\n<p>اگر چہرہ تصویر میں ہو تو متن کو کنارے پر رکھیں۔ چہرہ صاف رہے اور متن بھی پڑھا جا سکے۔</p>\n<p>چہرے کے قریب متن رکھنے سے لوگ متن کے بجائے چہرہ دیکھتے ہیں۔ متن کی جگہ چہرے سے دور رکھیں۔</p>\n<h2 id=\"hierarchy\">متن کی درجہ بندی</h2>\n<p>درجہ بندی کا مطلب ہے کہ سب سے اہم متن سب سے بڑا اور نمایاں ہو۔ لوگ پہلے بڑا متن پڑھتے ہیں، پھر چھوٹا۔</p>\n<p>درجہ بندی سائز، رنگ اور وزن سے بنتی ہے۔ عنوان بڑا اور بولڈ، تفصیل چھوٹی اور ہلکی۔</p>\n<p>درجہ بندی کے بغیر سب متن ایک جیسا لگتا ہے اور لوگ نہیں جانتے کہ پہلے کیا پڑھیں۔</p>\n<h2 id=\"testing-small-screens\">چھوٹی اسکرین پر جانچ</h2>\n<p>تصویر کو فون پر دیکھ کر جانچیں۔ کمپیوٹر پر جو متن پڑھا جاتا ہے، وہ فون پر چھوٹا ہو جاتا ہے۔</p>\n<p>چھوٹی اسکرین پر جانچنے سے معلوم ہوتا ہے کہ متن کافی بڑا ہے یا نہیں۔ اگر فون پر متن نہ پڑھا جا سکے تو سائز بڑھائیں۔</p>\n<p>جانچ کے لیے تصویر کو اصل سائز میں فون پر دیکھیں، زوم کر کے نہیں۔ زوم کرنا دھوکا دیتا ہے۔</p>\n<h2 id=\"accessibility\">رسائی اور متن</h2>\n<p>رسائی کا مطلب ہے کہ ہر کوئی متن پڑھ سکے، بشمول کمزور نظر والے لوگ۔ کنٹراسٹ 4.5:1 سے کم نہ رکھیں۔</p>\n<p>رنگ اندھے لوگوں کے لیے متن صرف رنگ سے الگ نہ کریں۔ سائز اور وزن سے بھی فرق کریں۔</p>\n<p>رسائی کے لیے متن کو تصویر کے اندر نہ لکھیں، بلکہ الگ سے بھی دیں۔ اسکرین ریڈر تصویر کے اندر کا متن نہیں پڑھتا۔</p>\n<h2 id=\"common-readability-mistakes\">عام پڑھنے کی غلطیاں</h2>\n<p>سب سے عام غلطی کم کنٹراسٹ ہے: ہلکے پس منظر پر ہلکا متن۔ کنٹراسٹ ناپ کر دیکھیں۔</p>\n<p>دوسری غلطی بہت چھوٹا متن ہے، جو فون پر پڑھا نہیں جاتا۔ متن بڑا رکھیں۔</p>\n<p>تیسری غلطی بہت زیادہ متن ہے۔ تصویر پر صرف ضروری الفاظ لکھیں، تفصیل کیپشن میں دیں۔</p>\n<h2 id=\"readability-checklist\">پڑھنے کی اہلیت کی چیک لسٹ</h2>\n<p>چیک لسٹ یہ ہے: کنٹراسٹ 4.5:1 یا زیادہ، فونٹ سادہ، سائز فون پر پڑھنے کے قابل، متن تصویر کے سادہ حصے میں۔</p>\n<p>چیک لسٹ کا آخری نکتہ یہ ہے کہ تصویر کو کسی اور کو دکھائیں۔ اگر وہ متن پڑھ سکے تو تصویر تیار ہے۔</p>\n<p>چیک لسٹ کو ہر تصویر پر استعمال کریں۔ یہ عادت بن جائے تو غلطیاں ختم ہو جاتی ہیں۔ مزید تفصیل <a href=\"/ur/blog/tasveer-par-text-kaise-likhein/\">تصویر پر متن کیسے شامل کریں</a> میں اور واٹر مارک کے اصول <a href=\"/ur/blog/tasveer-watermark-rehnumai/\">واٹر مارک گائیڈ</a> میں دیکھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"تصویر پر متن پڑھنا مشکل کیوں ہوتا ہے؟","answer":"کیونکہ متن اور پس منظر کا کنٹراسٹ کم ہوتا ہے، یا تصویر مصروف ہوتی ہے۔ کنٹراسٹ بڑھائیں، سادہ جگہ چنیں، یا پینل لگائیں۔"},{"question":"آؤٹ لائن بہتر ہے یا سایہ؟","answer":"دونوں کام کرتے ہیں۔ آؤٹ لائن مصروف تصویر پر بہتر ہے، سایہ ہلکی تصویر پر۔ ایک چنیں، دونوں ایک ساتھ نہ لگائیں۔"},{"question":"فون فیڈ کے لیے متن کتنا بڑا ہونا چاہیے؟","answer":"اتنا بڑا کہ فون پر بغیر زوم کے پڑھا جا سکے۔ تصویر کو فون پر دیکھ کر جانچیں۔ اگر متن پڑھا جا سکے تو سائز درست ہے۔"},{"question":"متن کے لیے تصویر کی بہترین جگہ کون سی ہے؟","answer":"تصویر کا سادہ حصہ، جہاں رنگ ایک جیسا ہو۔ اکثر کنارے سادہ ہوتے ہیں۔ چہرے اور مصروف حصے سے دور رکھیں۔"},{"question":"ایک تصویر پر کتنے فونٹ استعمال کریں؟","answer":"ایک یا دو۔ زیادہ فونٹ تصویر کو بے ترتیب بنا دیتے ہیں۔ ایک فونٹ عنوان کے لیے، دوسرا تفصیل کے لیے کافی ہے۔"},{"question":"رنگ اندھے ناظرین کے لیے متن کا رنگ کیسے چنیں؟","answer":"صرف رنگ پر انحصار نہ کریں۔ کنٹراسٹ زیادہ رکھیں اور سائز و وزن سے بھی فرق کریں، تاکہ متن رنگ کے بغیر بھی الگ نظر آئے۔"}];
